from engine import span
def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='Las células obtienen la energía que usan de una molécula, el ATP, y la producen sobre todo en las mitocondrias mediante la respiración celular. Este capítulo describe el ATP y su energía, las etapas de la respiración, cuánto ATP rinde una molécula de glucosa y por qué las fuentes dan cifras distintas, y el papel de las mitocondrias.',
        quotes=[Q('es_atp','es un nucleótido fundamental en la obtención de energía celular'), Q('en_atp','it is often referred to as the "molecular unit of currency" for intracellular energy transfer')]))
    P.append(dict(text='El ATP, adenosín trifosfato, está formado por un azúcar de tipo ribosa unido a una base nitrogenada, la adenina, y a tres grupos fosfato. Su fórmula molecular es C10H16N5O13P3. Se produce durante la fotofosforilación y la respiración celular, y lo consumen muchas enzimas en la catálisis de numerosos procesos. Cuando se consume en un proceso metabólico, el ATP se convierte en ADP o en AMP, y otros procesos, como la fosforilación oxidativa, lo regeneran.',
        quotes=[Q('es_atp','Está formado por un azúcar de tipo ribosa unido a una base nitrogenada adenina (por el carbono uno) y a tres grupos fosfato.'), Q('es_atp','Su fórmula molecular es C10H16N5O13P3.'), Q('en_atp','When consumed in a metabolic process, ATP converts either to adenosine diphosphate (ADP) or to adenosine monophosphate (AMP).')]))
    P.append(dict(text='Las fuentes dan dos valores para la energía del ATP y es importante no confundirlos. La hidrólisis de ATP a ADP y fosfato inorgánico libera −30,5 kJ/mol (−7,3 kcal/mol) en condiciones estándar, cuando todos los metabolitos están a 1 mol/L. En cambio, el inicio de una de las fuentes habla de una energía libre de aproximadamente 58 kJ/mol para impulsar los procesos celulares. La fuente explica que la energía libre real depende de las concentraciones y que, en condiciones citoplasmáticas, con la relación ADP/ATP a diez órdenes de magnitud del equilibrio, es de alrededor de −57 kJ/mol. Así, 30,5 kJ/mol es la cifra estándar y los 58 kJ/mol del inicio de la fuente son una cifra en condiciones celulares, no una contradicción.',
        quotes=[Q('en_atp','releases ΔG°\' = −30.5 kJ/mol (−7.3 kcal/mol) of Gibbs free energy under standard conditions when all metabolite concentrations are 1 mol/L'), Q('es_atp','ATP + H2O → ADP + Pi ΔH = −30.5 kJ/mol (−7.3 kcal/mol)'), Q('en_atp','provides free energy of approximately 58 kJ/mol (0.6 eV) to drive and support many processes in living cells'), Q('en_atp','At cytoplasmic conditions, where the ADP/ATP ratio is 10 orders of magnitude from equilibrium, the ΔG is around −57 kJ/mol.')]))
    P.append(dict(text='El ATP no se almacena, se recicla. Un adulto recicla cada día, por síntesis e hidrólisis, unos 50 kilogramos de ATP, que son unos 100 moles. La energía usada por las células de un adulto exige la hidrólisis de entre 100 y 150 mol de ATP al día, de modo que una persona usa en un día una cantidad de ATP comparable a su peso. Cada molécula de ATP se recicla entre 1000 y 1500 veces en un solo día, a unos 9×10^20 moléculas por segundo. Las células vivas mantienen la proporción de ATP a ADP lejos del equilibrio, con concentraciones de ATP cinco veces mayores que la de ADP.',
        quotes=[Q('en_atp','Daily, an average adult human recycles through synthesis and hydrolysis around 50 kilograms of ATP (about 100 moles).'), Q('en_atp','The energy used by human cells in an adult requires the hydrolysis of 100 to 150 mol/L of ATP daily'), Q('en_atp','Each equivalent of ATP is recycled 1000–1500 times during a single day'), Q('es_atp','con concentraciones de ATP cinco veces mayores que la concentración de ADP')]))
    P.append(dict(text='La respiración celular es un proceso metabólico que consiste en oxidar nutrientes y obtener energía de ellos en forma de ATP, para lo cual se requiere un aceptor final de electrones. Si el aceptor es el oxígeno, se habla de respiración aeróbica, y si es otra molécula, de respiración anaeróbica. Los carbohidratos, lípidos y proteínas pueden consumirse como fuente de energía y terminan oxidados a dióxido de carbono y agua. En las eucariotas, la respiración aeróbica tiene lugar en las mitocondrias, aunque la fase previa de glucólisis es citosólica.',
        quotes=[Q('es_respiracion','La respiración celular es un proceso metabólico que consiste en oxidar nutrientes y obtener energía de ellos en forma de ATP'), Q('en_respiration','If the electron acceptor is oxygen, the process is more specifically known as aerobic cellular respiration.'), Q('es_respiracion','En eucariotas, la respiración celular aeróbica tiene lugar en las mitocondrias, aunque la fase glucolítica previa es citosólica.')]))
    P.append(dict(text='La respiración aeróbica se produce en tres etapas: glucólisis, ciclo de Krebs y cadena de transporte de electrones. La glucólisis consta de diez reacciones enzimáticas en las que la glucosa, de seis carbonos, se convierte en dos moléculas de piruvato, de tres carbonos, sin pérdida de carbono en forma de CO2. Los electrones que pierden los sustratos son recogidos por coenzimas y se transfieren a la cadena de transporte de electrones, donde se produce ATP durante la fosforilación oxidativa. También se producen pequeñas cantidades de ATP en la glucólisis y en el ciclo de Krebs por fosforilación a nivel de sustrato.',
        quotes=[Q('es_respiracion','se produce en tres etapas:  glucólisis, ciclo de Krebs y cadena de transporte de electrones'), Q('es_respiracion','Consta de 10 reacciones enzimáticas en las que la glucosa (molécula de 6 carbonos) se convierte en dos moléculas de piruvato (molécula de 3 carbonos)'), Q('en_respiration','Biology textbooks often state that 38 ATP molecules can be made per oxidized glucose molecule during cellular respiration (2 from glycolysis, 2 from the Krebs cycle, and about 34 from the electron transport system).')]))
    P.append(dict(text='El rendimiento de ATP por molécula de glucosa muestra cómo cambia una cifra al precisar su condición. Se suele decir que el máximo teórico es de 36 a 38 ATP, con 2 de la glucólisis, 2 del ciclo de Krebs y el resto de la fosforilación oxidativa. Pero las dos fuentes advierten de que esa cifra no se alcanza porque hay pérdidas por membranas con fugas y por el coste de mover piruvato, fosfato y ADP a la matriz mitocondrial, y estiman en condiciones reales entre 29 y 30 ATP por glucosa.',
        quotes=[Q('es_respiracion','se estima que la producción de ATP por molécula de glucosa es de 36 a 38'), Q('en_respiration','However, this maximum yield is never quite reached because of losses due to leaky membranes as well as the cost of moving pyruvate and ADP into the mitochondrial matrix, and current estimates range around 29 to 30 ATP per glucose.'), Q('es_respiracion','en condiciones de células reales el rendimiento es menor, y se estima en 29 a 30 ATP por glucosa')]))
    P.append(dict(text='Las dos fuentes comparan también la respiración aeróbica con la fermentación anaerobia, que produce solo 2 ATP por glucosa, pero dan razones distintas: una dice que el metabolismo aeróbico es 19 veces más eficiente y la otra que lo es hasta 15 veces. Los dos números son coherentes con el rendimiento que cada una tiene en mente: 38 dividido entre 2 es 19, y 30 dividido entre 2 es 15. La diferencia de «19 veces» frente a «15 veces» se debe, por tanto, a si se usa el máximo teórico o la estimación realista, no a un desacuerdo sobre la fermentación.',
        quotes=[Q('es_respiracion','El metabolismo aeróbico es 19 veces más eficiente que el anaeróbico fermentativo (que solo produce 2 moles de ATP por mol de glucosa)'), Q('en_respiration','Aerobic metabolism is up to 15 times more efficient than anaerobic metabolism (which yields 2 molecules of ATP per 1 molecule of glucose).')]))
    P.append(dict(text='Las mitocondrias son orgánulos con doble membrana que usan respiración aeróbica para generar ATP, que se emplea en toda la célula como fuente de energía química. Fueron descubiertas por Albert von Kölliker en 1857 en los músculos voluntarios de insectos, y el término mitocondria, «gránulo en forma de hilo», lo acuñó Carl Benda en 1898. Contienen sus propios cromosomas pequeños.',
        quotes=[Q('en_mitochondrion','Mitochondria have a double membrane structure and use aerobic respiration to generate adenosine triphosphate (ATP)'), Q('en_mitochondrion','They were discovered by Albert von Kölliker in 1857 in the voluntary muscles of insects.'), Q('nhgri_mito','Mitochondria contain their own small chromosomes.')]))
    P.append(dict(text='Según la teoría endosimbiótica, hace unos 2500 millones de años una célula procariota capaz de usar oxígeno molecular como oxidante fue fagocitada por otra célula sin ser digerida, y se estableció una simbiosis permanente en la que la célula fagocitada proporcionaba energía en forma de ATP. Es la base de la aceptación general de la simbiogénesis: los ancestros procariotas de las mitocondrias modernas se fusionaron con células eucariotas hace mucho tiempo. Las mitocondrias, y por tanto su ADN, se heredan solo de la madre, con raras excepciones.',
        quotes=[Q('es_mitocondria','hace unos 2500 millones de años'), Q('en_mitochondrion','free-living prokaryotic ancestors of modern mitochondria permanently fused with eukaryotic cells in the distant past'), Q('nhgri_mito','Generally, mitochondria, and therefore mitochondrial DNA, are inherited only from the mother.')]))
    P.append(dict(role='definition', text='ATP: nucleótido formado por adenina, ribosa y tres grupos fosfato, que transfiere energía química en la célula. Se produce en la respiración celular y se recicla constantemente a partir de ADP.',
        quotes=[Q('es_atp','es un nucleótido fundamental en la obtención de energía celular'), Q('en_atp','Other processes, such as oxidative phosphorylation or substrate-level phosphorylation, regenerate ATP.')]))
    P.append(dict(role='consejo', text='Cuando dos fuentes den cifras de rendimiento distintas, pregunte siempre por la condición: máximo teórico o estimación real, condiciones estándar o fisiológicas. Compruebe además si la razón que citan, como 19 o 15 veces, sale de dividir sus propias cifras.',
        quotes=[Q('es_respiracion','Pero esta es una cifra máxima teórica'), Q('en_respiration','Although there is a theoretical yield of 38 ATP molecules per glucose during cellular respiration')]))
    P.append(dict(role='self_check', text='¿Qué diferencia hay entre los 30,5 kJ/mol y los 58 kJ/mol que las fuentes dan para el ATP? ¿Qué tres etapas tiene la respiración aeróbica? ¿Por qué se dice a veces que el aeróbico es 19 veces más eficiente y otras 15 veces?',
        quotes=[Q('en_respiration','current estimates range around 29 to 30 ATP per glucose'), Q('es_atp','ATP + H2O → ADP + Pi ΔH = −30.5 kJ/mol (−7.3 kcal/mol)')]))
    return P

def problems(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    return [dict(role='worked', problem_type='NUMERICAL',
        prompt='Una fuente dice que un adulto recicla al día unos 50 kg de ATP, unos 100 moles. Otra da la fórmula C10H16N5O13P3 para el ATP. Con masas atómicas de C 12,011, H 1,008, N 14,007, O 15,999 y P 30,974 g/mol, calcule la masa molar del ATP, los moles que corresponden a 50 kg y comprobar si encajan con los 100 moles de la fuente.',
        expected='98.6', quotes=[Q('en_atp','Daily, an average adult human recycles through synthesis and hydrolysis around 50 kilograms of ATP (about 100 moles).'), Q('es_atp','Su fórmula molecular es C10H16N5O13P3.')],
        method='Masa molar a partir de la fórmula y conversión de masa a moles',
        solution=dict(given=[dict(symbol='m',value=50,unit='kg',meaning='masa de ATP reciclada por día'),dict(symbol='n_C',value=10,unit='dimensionless',meaning='átomos de C'),dict(symbol='n_H',value=16,unit='dimensionless',meaning='átomos de H'),dict(symbol='n_N',value=5,unit='dimensionless',meaning='átomos de N'),dict(symbol='n_O',value=13,unit='dimensionless',meaning='átomos de O'),dict(symbol='n_P',value=3,unit='dimensionless',meaning='átomos de P')],
          unknown='La masa molar del ATP, los moles en 50 kg y su comparación con 100 mol.',
          model=[dict(name='Masa molar',latex='M = 10\\,M_C + 16\\,M_H + 5\\,M_N + 13\\,M_O + 3\\,M_P',symbolic='10*12.011+16*1.008+5*14.007+13*15.999+3*30.974'),dict(name='Moles',latex='n = m / M',symbolic='50000/M')],
          assumptions=['Se usan masas atómicas estándar redondeadas a tres decimales.','Se desprecia la forma iónica del ATP en solución.'],
          development=['La masa molar se obtiene sumando las masas de los átomos de la fórmula; los 50 kg se pasan a gramos antes de dividir.'],
          steps=[dict(text='Masa molar del ATP, en g/mol',equation='M = 10(12{,}011)+16(1{,}008)+5(14{,}007)+13(15{,}999)+3(30{,}974)',expression='10*12.011+16*1.008+5*14.007+13*15.999+3*30.974',expected=507.181,unit='dimensionless'),
                 dict(text='Moles en 50 kg',equation='n = 50\\,000 / 507{,}181',expression='50000/507.181',expected=98.58,unit='dimensionless')],
          result='La masa molar del ATP es de unos 507,2 g/mol y 50 kg equivalen a unos 98,6 mol, que concuerdan con los «unos 100 moles» de la fuente (diferencia del 1,4 %).',
          interpretation='La relación de 50 kg a 100 mol es coherente con la fórmula química, así que las dos cifras de la fuente se pueden usar juntas.',
          limitations=['La cifra de 100 mol es redondeada; el cálculo comprueba el orden de magnitud, no el valor exacto.'],
          mistakes=['Dividir 50 kg entre 507 g/mol sin pasar los kilogramos a gramos.']))]


